package com.adaptive.recovery;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;import java.util.concurrent.ConcurrentLinkedDeque;
@Service public class RecoveryEngineService {
 private final int window;private final long cooldown;private final double cpuThreshold,memoryThreshold,e2MemoryThreshold;private final Deque<RecoveryRecord> records=new ConcurrentLinkedDeque<>();private final PrometheusReader prometheus;private final KubernetesReader kubernetes;
 public RecoveryEngineService(int window,long cooldown,double cpuThreshold,double memoryThreshold,PrometheusReader prometheus,KubernetesReader kubernetes){this(window,cooldown,cpuThreshold,memoryThreshold,memoryThreshold,prometheus,kubernetes);}
 @org.springframework.beans.factory.annotation.Autowired public RecoveryEngineService(@Value("${recovery.persistence-window}")int window,@Value("${recovery.cooldown-seconds}")long cooldown,@Value("${recovery.cpu-threshold}")double cpuThreshold,@Value("${recovery.memory-threshold}")double memoryThreshold,@Value("${recovery.e2-memory-threshold:${recovery.memory-threshold}}")double e2MemoryThreshold,PrometheusReader prometheus,KubernetesReader kubernetes){this.window=window;this.cooldown=cooldown;this.cpuThreshold=cpuThreshold;this.memoryThreshold=memoryThreshold;this.e2MemoryThreshold=e2MemoryThreshold;this.prometheus=prometheus;this.kubernetes=kubernetes;}
 public synchronized RecoveryRecord evaluate(String service,boolean execute){return evaluate(service,execute,null);}
 public synchronized RecoveryRecord evaluate(String service,boolean execute,String profile){String target=service.endsWith("-service")?service:service+"-service";double selectedMemoryThreshold=("e2-memory".equals(profile)&&target.equals("adaptive-inventory-service"))?e2MemoryThreshold:memoryThreshold;Signals s=prometheus.read(target,window,kubernetes.healthy(target));if(target.equals("adaptive-inventory-service"))s=new Signals(kubernetes.cpuCores(target),kubernetes.memoryUsageRatio(target),s.readiness(),s.httpErrors(),s.latency(),s.dependencyUp(),s.dependencySuccesses(),s.persistenceSamples(),s.kubernetesHealthy());RecoveryDecision d;String reason;boolean verified=false;if(s.persistenceSamples()<window){d=RecoveryDecision.FAIL_SAFE;reason="persistence window incomplete";}else if(!Double.isFinite(s.cpu())||!Double.isFinite(s.memory())||!Double.isFinite(s.latency())||!Double.isFinite(s.httpErrors())){d=RecoveryDecision.FAIL_SAFE;reason="required signal unavailable";if(target.equals("adaptive-inventory-service"))reason+="; Inventory CPU/memory source: Kubernetes Metrics API; "+kubernetes.signalDiagnostics();reason+="; no action taken";}else if(!s.kubernetesHealthy()||!s.dependencyUp()){d=RecoveryDecision.FAIL_SAFE;reason="Kubernetes or dependency signal unavailable";if(target.equals("adaptive-inventory-service"))reason+="; "+kubernetes.signalDiagnostics();}else if(recentAction(service)){d=RecoveryDecision.OBSERVE;reason="cooldown active";}else if(s.cpu()>=cpuThreshold){d=RecoveryDecision.INCREASE_CPU;reason="CPU threshold exceeded; bounded action requires explicit execute=true";if(execute)verified=kubernetes.increaseCpu(service);}else if(s.memory()>=selectedMemoryThreshold){d=RecoveryDecision.INCREASE_MEMORY;reason="memory threshold exceeded ("+selectedMemoryThreshold+" ratio); bounded action requires explicit execute=true";if(execute)verified=kubernetes.increaseMemory(service);}else if(s.dependencySuccesses()>=0&&s.dependencySuccesses()<window){d=RecoveryDecision.OBSERVE;reason="repeated dependency checks not yet stable";}else{d=RecoveryDecision.CONTINUE;reason="signals within configured baseline";}RecoveryRecord r=new RecoveryRecord(Instant.now(),service,d,reason,s,verified);records.addFirst(r);while(records.size()>100)records.removeLast();return r;}
 public Collection<RecoveryRecord> records(){return List.copyOf(records);}private boolean recentAction(String service){Instant cutoff=Instant.now().minusSeconds(cooldown);return records.stream().anyMatch(r->r.service().equals(service)&&r.at().isAfter(cutoff)&&r.actionVerified()&&(r.decision()==RecoveryDecision.INCREASE_CPU||r.decision()==RecoveryDecision.INCREASE_MEMORY));}
}
